package dev.zomboid.clans;
import java.util.*;
public final class Pve {
 static final Map<UUID,Wave> waves=new HashMap<>();static final Random random=new Random();static final List<Cleanup> cleanups=new ArrayList<>();
 static final String[] SPECIAL={"mutantszombies:crawler","mutantszombies:blister_zombie","mutantszombies:spitter","mutantszombies:zombie_brute","mutantszombies:split_head_zombie","mutantszombies:rotten_mutant","mutantszombies:mutant_brute"};
 static class Wave {UUID id=UUID.randomUUID(),clan;Object level;long chunk,deadline;int rarity,pending,alive,killed,failures,stage=1,health;Set<UUID> participants=new HashSet<>(),fallen=new HashSet<>();Set<UUID> mobs=new HashSet<>();Set<Long> forced=new HashSet<>();Wave(UUID clan,Object level,long chunk,int r,long now){this.clan=clan;this.level=level;this.chunk=chunk;rarity=r;pending=PveRules.count(r);deadline=now+18000;}}
 static class Cleanup {Wave wave;Deque<UUID> waiting;Map<UUID,Long> fading=new HashMap<>();int batch;long next;Cleanup(Wave w,long now){wave=w;waiting=new ArrayDeque<>(w.mobs);batch=Math.max(1,(waiting.size()+11)/12);next=now+20;}}
 static Object ticketType;
 static Object ticket(){if(ticketType==null)ticketType=R.call(R.type("net.minecraft.server.level.TicketType"),"create","factionfriction_pve",Comparator.<String>naturalOrder());return ticketType;}
 static void keepLoaded(Wave w){Object source=R.call(w.level,"getChunkSource");int x=(int)w.chunk,z=(int)(w.chunk>>32);for(int dx=-2;dx<=2;dx++)for(int dz=-2;dz<=2;dz++){Object chunk=R.make("net.minecraft.world.level.ChunkPos",x+dx,z+dz);R.call(source,"addRegionTicket",ticket(),chunk,2,w.id.toString());w.forced.add(((Number)R.call(chunk,"toLong")).longValue());R.call(w.level,"getChunk",x+dx,z+dz);}}
 static void releaseLoaded(Wave w){Object source=R.call(w.level,"getChunkSource");for(long c:w.forced)R.call(source,"removeRegionTicket",ticket(),R.make("net.minecraft.world.level.ChunkPos",(int)c,(int)(c>>32)),2,w.id.toString());w.forced.clear();}
 static void cleanupTick(Object server){long now=Clans.now(server);for(Cleanup c:new ArrayList<>(cleanups)){if(R.call(c.wave.level,"getServer")!=server)continue;for(var entry:new ArrayList<>(c.fading.entrySet()))if(now>=entry.getValue()){Object mob=R.call(c.wave.level,"getEntity",entry.getKey());if(mob!=null)R.call(mob,"discard");clearOutline(c.wave.level,entry.getKey());c.fading.remove(entry.getKey());}if(now>=c.next){c.next=now+20;for(int i=0;i<c.batch&&!c.waiting.isEmpty();i++){UUID id=c.waiting.remove();Object mob=R.call(c.wave.level,"getEntity",id);if(mob!=null&&R.yes(R.call(mob,"isAlive"))){R.call(mob,"setTarget",(Object)null);R.call(R.call(mob,"getNavigation"),"stop");R.call(mob,"hurt",R.call(R.call(mob,"damageSources"),"genericKill"),Float.MAX_VALUE);c.fading.put(id,now+20);}else clearOutline(c.wave.level,id);}}if(c.waiting.isEmpty()&&c.fading.isEmpty()){cleanups.remove(c);releaseLoaded(c.wave);}}}
 static Object tag(Object e){return R.call(e,"getPersistentData");}
 static String entityId(Object e){return R.call(R.get(R.type("net.minecraft.core.registries.BuiltInRegistries"),"ENTITY_TYPE"),"getKey",R.call(e,"getType")).toString();}
 public static void join(Object event){Object level=R.call(event,"getLevel");if(R.yes(R.call(level,"isClientSide")))return;Object e=R.call(event,"getEntity"),t=tag(e);String marker=R.call(t,"getString","FactionPveWave").toString();if(!marker.isEmpty()){boolean found=waves.values().stream().anyMatch(w->w.id.toString().equals(marker));if(!found)R.call(event,"setCanceled",true);return;}if(R.yes(R.call(event,"loadedFromDisk")))return;if(!R.type("net.minecraft.world.entity.Mob").isInstance(e))return;String type=entityId(e);if(!java.util.Set.of("minecraft:zombie","minecraft:husk","minecraft:drowned","minecraft:zombie_villager","minecraft:zombified_piglin","minecraft:zoglin","minecraft:zombie_horse").contains(type)&&!type.startsWith("mutantszombies:"))return;Object m=Clans.manager(R.call(level,"getServer"));long chunk=((Number)R.call(R.call(e,"chunkPosition"),"toLong")).longValue();if(((Map<?,?>)R.call(m,"getChunkOwnerMap")).containsKey(chunk))R.call(event,"setCanceled",true);}
 public static void action(Object p,boolean accept){Object server=R.call(p,"getServer"),m=Clans.manager(server),f=Clans.mine(m,p);if(f==null||!Clans.authority(f,p)){Clans.say(p,"Solo jefatura/comandantes pueden solicitar oleadas.");return;}UUID id=Clans.fid(f);ClanState.Profile profile=Clans.state(m).profile(id);long now=Clans.now(server);if(waves.containsKey(id)){Clans.say(p,"Tu clan ya tiene una oleada activa.");return;}if(!accept){if(now<profile.pveNext){Clans.say(p,"Espera antes de solicitar otra oferta de oleada.");return;}if(profile.offer>=0&&now<profile.offerEnd){Clans.say(p,"Ya tienes una oferta vigente; no hace falta solicitar otra.");Clans.snapshot(p,m);return;}profile.offer=PveRules.rarity(random.nextInt(100));profile.offerEnd=now+6000;Clans.dirty(m);Clans.say(p,"Oferta "+PveRules.label(profile.offer)+": "+PveRules.count(profile.offer)+" infectados. Acéptala en los próximos 5 minutos.");Clans.snapshot(p,m);return;}if(profile.offer<0||now>=profile.offerEnd){Clans.say(p,"Solicita primero una oferta vigente.");return;}if(now<profile.pveNext){Clans.say(p,"Hay cinco minutos de enfriamiento entre defensas.");return;}if(((Number)R.call(f,"getClaimCount")).intValue()<1||!profile.nexusPlaced){Clans.say(p,"Reclama al menos un chunk y coloca el nexo antes de iniciar.");return;}Object level=R.call(p,"level");if(!R.yes(R.call(level,"hasChunkAt",Nexus.pos(profile)))){Clans.say(p,"Acércate al nexo para cargar su zona antes de empezar.");return;}if(!Nexus.exists(level,profile)){profile.nexusPlaced=false;profile.nexusIssued=false;Clans.dirty(m);Clans.say(p,"El nexo no está colocado. Solicita otro al jefe.");return;}if(!R.call(R.call(level,"dimension"),"location").toString().equals("minecraft:overworld")){Clans.say(p,"Las oleadas se organizan en el Overworld.");return;}long chunk=((Number)R.call(R.make("net.minecraft.world.level.ChunkPos",Nexus.pos(profile)),"toLong")).longValue();if(!id.equals(((Map<?,?>)R.call(m,"getChunkOwnerMap")).get(chunk))){Clans.say(p,"Sitúate dentro de un chunk de tu clan para aceptar.");return;}if(waves.size()>=3){Clans.say(p,"Ya hay tres oleadas activas; espera a que termine alguna.");return;}if(profile.offer>0&&!available(SPECIAL[0])){Clans.say(p,"Esta oleada requiere Mutants Zombies instalado en el servidor.");return;}Wave w=new Wave(id,level,chunk,profile.offer,now);w.health=Nexus.maxHealth(profile);for(UUID u:Clans.members(f).keySet()){Object member=Clans.online(server,u);if(member!=null&&R.yes(R.call(member,"isAlive"))&&R.call(member,"level")==level&&id.equals(((Map<?,?>)R.call(m,"getChunkOwnerMap")).get(((Number)R.call(R.call(member,"chunkPosition"),"toLong")).longValue())))w.participants.add(u);}if(w.participants.isEmpty()){Clans.say(p,"Debe haber al menos un participante conectado dentro de la base.");return;}waves.put(id,w);keepLoaded(w);Object first=Clans.online(server,w.participants.iterator().next());if(!spawn(w,first)){waves.remove(id);releaseLoaded(w);Clans.say(p,"No hay espacio accesible para los enemigos cerca del nexo. Colócalo cerca de una entrada abierta o un patio; la oferta se conserva.");return;}profile.offer=-1;profile.pveNext=now+6000;Clans.dirty(m);Clans.notify(server,f,"Oleada "+PveRules.label(w.rarity)+" iniciada: "+w.pending+" enemigos. Puedes salir del territorio: defiende el nexo para ganar.");Clans.snapshot(p,m);}
 static boolean available(String id){Object registry=R.get(R.type("net.minecraft.core.registries.BuiltInRegistries"),"ENTITY_TYPE"),key=R.call(R.type("net.minecraft.resources.ResourceLocation"),"parse",id);return R.yes(R.call(registry,"containsKey",key));}
 static void outline(Object level,Object mob){Object board=R.call(level,"getScoreboard"),team=R.call(board,"getPlayerTeam","zomboid_pve");if(team==null)team=R.call(board,"addPlayerTeam","zomboid_pve");R.call(team,"setColor",R.get(R.type("net.minecraft.ChatFormatting"),"RED"));R.call(board,"addPlayerToTeam",R.call(mob,"getUUID").toString(),team);R.call(mob,"setGlowingTag",true);}
 static void clearOutline(Object level,UUID id){R.call(R.call(level,"getScoreboard"),"removePlayerFromTeam",id.toString());}
 static boolean inside(Object manager,Wave w,Object player){return R.call(player,"level")==w.level&&w.clan.equals(((Map<?,?>)R.call(manager,"getChunkOwnerMap")).get(((Number)R.call(R.call(player,"chunkPosition"),"toLong")).longValue()));}
 static int[] candidate(int x,int z){int dx=random.nextInt(49)-24,dz=random.nextInt(49)-24;if(Math.max(Math.abs(dx),Math.abs(dz))<8)dx=dx<0?-8:8;return new int[]{x+dx,z+dz};}
 static boolean spawn(Wave w,Object target){Object bp=Nexus.pos(Clans.state(Clans.manager(R.call(w.level,"getServer"))).profile(w.clan));int nx=(int)R.coord(bp,"X"),ny=(int)R.coord(bp,"Y"),nz=(int)R.coord(bp,"Z");for(int attempt=0;attempt<24;attempt++){int[] xy=candidate(nx,nz);double px=xy[0]+.5,pz=xy[1]+.5;for(int py:Siege.heights(((Number)R.call(w.level,"getMinBuildHeight")).intValue()+1,((Number)R.call(w.level,"getMaxBuildHeight")).intValue()-2,((Number)R.call(w.level,"getSeaLevel")).intValue()+1)){Object pos=R.make("net.minecraft.core.BlockPos",xy[0],py-1,xy[1]);if(!R.yes(R.call(w.level,"hasChunkAt",pos))||!R.yes(R.call(R.call(w.level,"getBlockState",pos),"isSolidRender",w.level,pos)))continue;if(target!=null&&R.call(target,"level")==w.level&&R.num(R.call(target,"distanceToSqr",px,(double)py,pz))<36)continue;boolean special=w.pending<=PveRules.special(w.rarity);String id=special?SPECIAL[w.rarity==1?random.nextInt(3):w.rarity==2?2+random.nextInt(3):w.rarity==3?3+random.nextInt(4):5+random.nextInt(2)]:"minecraft:zombie";if(!available(id))id=SPECIAL[0];Object type=R.call(R.get(R.type("net.minecraft.core.registries.BuiltInRegistries"),"ENTITY_TYPE"),"get",R.call(R.type("net.minecraft.resources.ResourceLocation"),"parse",id)),mob=R.call(type,"create",w.level);if(mob==null)continue;R.call(mob,"moveTo",px,(double)py,pz,0f,0f);if(!R.yes(R.call(w.level,"noCollision",mob))||!R.yes(R.call(R.call(R.call(w.level,"getBlockState",R.make("net.minecraft.core.BlockPos",xy[0],py,xy[1])),"getFluidState"),"isEmpty")))continue;R.call(tag(mob),"putString","FactionPveWave",w.id.toString());R.call(mob,"setPersistenceRequired");R.call(mob,"setTarget",target!=null&&R.call(target,"level")==w.level?target:null);R.call(R.get(mob,"goalSelector"),"addGoal",0,Nexus.goal(mob));if(!R.yes(R.call(w.level,"addFreshEntity",mob)))continue;outline(w.level,mob);w.mobs.add((UUID)R.call(mob,"getUUID"));w.pending--;w.alive++;return true;}}return false;}
 public static void death(Object event){if(R.yes(R.call(event,"isCanceled")))return;Object mob=R.call(event,"getEntity"),level=R.call(mob,"level");if(R.yes(R.call(level,"isClientSide")))return;if(R.type("net.minecraft.server.level.ServerPlayer").isInstance(mob)){UUID participant=Clans.id(mob);for(Wave w:new ArrayList<>(waves.values()))if(w.participants.contains(participant)){w.fallen.add(participant);boolean survivor=false;for(UUID u:w.participants){Object player=Clans.online(R.call(level,"getServer"),u);if(player!=null&&!w.fallen.contains(u)&&R.yes(R.call(player,"isAlive"))){survivor=true;break;}}if(!survivor)end(R.call(level,"getServer"),Clans.manager(R.call(level,"getServer")),w,false);}}String marker=R.call(tag(mob),"getString","FactionPveWave").toString();if(marker.isEmpty())return;for(Wave w:waves.values())if(w.id.toString().equals(marker)&&w.mobs.remove((UUID)R.call(mob,"getUUID"))){clearOutline(w.level,(UUID)R.call(mob,"getUUID"));w.alive--;Object killer=R.call(R.call(event,"getSource"),"getEntity");if(killer!=null&&R.type("net.minecraft.server.level.ServerPlayer").isInstance(killer)){Object f=Clans.mine(Clans.manager(R.call(level,"getServer")),killer);if(f!=null&&Clans.fid(f).equals(w.clan))w.killed++;}break;}}
 public static void tick(Object server){cleanupTick(server);long now=Clans.now(server);Object m=Clans.manager(server);for(Wave w:new ArrayList<>(waves.values())){Object f=Clans.faction(m,w.clan),target=null;if(f!=null)for(UUID u:w.participants){Object p=Clans.online(server,u);if(p!=null&&!w.fallen.contains(u)&&R.yes(R.call(p,"isAlive"))&&R.call(p,"level")==w.level){target=p;break;}}ClanState.Profile nexusProfile=Clans.state(m).profile(w.clan);if(R.yes(R.call(w.level,"hasChunkAt",Nexus.pos(nexusProfile)))&&!Nexus.exists(w.level,nexusProfile)){nexusProfile.nexusPlaced=false;nexusProfile.nexusIssued=false;Clans.dirty(m);end(server,m,w,false);continue;}if(f==null||w.fallen.containsAll(w.participants)){end(server,m,w,false);continue;}for(UUID u:w.participants){Object player=Clans.online(server,u);if(player!=null)R.call(player,"displayClientMessage",R.call(R.type("net.minecraft.network.chat.Component"),"literal","Nexo "+w.health+" PV · fase "+w.stage+" / 3 · enemigos "+(w.pending+w.alive)),true);}if(w.pending>0){boolean spawned=false;for(int i=0;i<3&&w.pending>0;i++){if(!spawn(w,target))break;spawned=true;}if(spawned)w.failures=0;if(!spawned&&++w.failures%60==0)Clans.notify(server,f,"Buscando acceso al nexo para los enemigos pendientes. La defensa continúa.");}if(w.pending==0&&w.alive==0){if(w.stage<3){w.stage++;w.pending=PveRules.count(w.rarity);Clans.notify(server,f,"Fase "+w.stage+" / 3. El nexo conserva "+w.health+" de vida.");}else end(server,m,w,w.health>0);}}}
 static void end(Object server,Object m,Wave w,boolean success){if(waves.get(w.clan)!=w)return;waves.remove(w.clan);w.pending=0;if(w.mobs.isEmpty())releaseLoaded(w);else cleanups.add(new Cleanup(w,Clans.now(server)));Object f=Clans.faction(m,w.clan);if(f==null)return;ClanState.Profile p=Clans.state(m).profile(w.clan);p.pveNext=Clans.now(server)+6000;if(success){p.pveXp+=PveRules.xp(w.rarity);p.pveWins++;int level=Math.max(Limits.level(R.call(f,"getTier")),PveRules.level(p.pveXp));R.call(f,"setTier",R.get(R.type("me.danialisntcool.factionfriction.faction.FactionTier"),new String[]{"TEAM","COLONY","COUNTRY"}[level-1]));int lots=1+w.rarity;for(var item:ClanConfig.INSTANCE.bundle.entrySet())p.rewards.merge(item.getKey(),item.getValue()*lots,Integer::sum);p.rewards.merge("minecraft:iron_ingot",4+4*w.rarity,Integer::sum);if(w.rarity>=1)p.rewards.merge("minecraft:iron_chestplate",1,Integer::sum);if(w.rarity>=2)p.rewards.merge("minecraft:diamond_sword",1,Integer::sum);if(w.rarity>=3)p.rewards.merge("minecraft:diamond_chestplate",1,Integer::sum);if(w.rarity==4)p.rewards.merge("minecraft:netherite_scrap",2,Integer::sum);if(w.rarity>=2)p.rewards.merge("minecraft:diamond",w.rarity-1,Integer::sum);if(w.rarity>=3)p.rewards.merge("minecraft:golden_apple",w.rarity-2,Integer::sum);Clans.notify(server,f,"Oleada superada: +"+PveRules.xp(w.rarity)+" XP; nivel "+level+"; recompensas en Depósito.");}else Clans.notify(server,f,"Oleada fallida o interrumpida. No concede XP ni recompensas.");Clans.dirty(m);}
 public static void stop(Object event){Object server=R.call(event,"getServer"),m=Clans.manager(server);for(Wave w:new ArrayList<>(waves.values()))if(R.call(w.level,"getServer")==server)end(server,m,w,false);for(Cleanup c:new ArrayList<>(cleanups))if(R.call(c.wave.level,"getServer")==server){for(UUID id:c.wave.mobs){Object mob=R.call(c.wave.level,"getEntity",id);if(mob!=null)R.call(mob,"discard");clearOutline(c.wave.level,id);}cleanups.remove(c);releaseLoaded(c.wave);}}
 public static void snapshot(Object m,Object f,StringBuilder out){ClanState.Profile p=Clans.state(m).profile(Clans.fid(f));Wave w=waves.get(Clans.fid(f));out.append(ClanState.row("PVE",String.valueOf(p.pveXp),String.valueOf(p.pveWins),p.offer<0||Clans.now(Clans.state(m).server.get())>=p.offerEnd?"Sin oferta":PveRules.label(p.offer),w==null?"Sin oleada activa":PveRules.label(w.rarity)+" · fase "+w.stage+"/3 · nexo "+w.health+" PV · pendientes "+(w.pending+w.alive)+" · bajas del clan "+w.killed));out.append(ClanState.row("NEXUS",String.valueOf(p.nexusIssued),String.valueOf(p.nexusPlaced),String.valueOf(Nexus.maxHealth(p)),String.valueOf(p.nexusUpgrade),String.valueOf(Math.max(0,(p.pveNext-Clans.now(Clans.state(m).server.get())+19)/20))));int rank=0;for(Object clan:Clans.factions(m).values().stream().sorted(java.util.Comparator.comparingInt((Object c)->Clans.state(m).profile(Clans.fid(c)).pveXp).reversed().thenComparing(java.util.Comparator.comparingInt((Object c)->Clans.state(m).profile(Clans.fid(c)).pveWins).reversed()).thenComparing(c->R.call(c,"getName").toString(),String.CASE_INSENSITIVE_ORDER)).toList()){ClanState.Profile other=Clans.state(m).profile(Clans.fid(clan));out.append(ClanState.row("TOP",String.valueOf(++rank),R.call(clan,"getName").toString(),String.valueOf(other.pveXp),String.valueOf(other.pveWins)));if(rank>=10)break;}}
}
